Object.assign(window.CONTEXTS,{"110-5-48-50":{"text":"小朱對潮流敏感度十足，也喜歡研究穿搭，就讀大學期間，常將自己穿過的古著類型服飾，透過 FB 社\n團和 Instagram 社群與網友交易，如此一來，除了常有新衣服可以替換，還能賺回一些零用錢。大學畢業後，\n小朱想擴大經營，計畫開間小型的實體店面，並且透過網路經營自己的服飾品牌。"}});
window.QUESTIONS.push(...[{"id":"110-5-A-26","exam":"110-5","q":26,"unit":"電腦與數位資料","topic":"數位科技","stem":"某校學生人數共有 1200 位，若以二進制編碼的方式來建立學生的學號，請問此校學生的學號至少須多\n少位元(bits)？","options":["3","10","11","100"],"answer":"C","official":"以二進位為 1200 位學生進行學號編碼，須產生 1200\n種不同的編碼，若學號編碼為 n bits，則 n 2 >= 1200，\n故 n 至少為 11"},{"id":"110-5-A-27","exam":"110-5","q":27,"unit":"電腦與數位資料","topic":"數位科技","stem":"某一廠牌 CPU 時脈頻率為 4G Hz，若此 CPU 執行每個指令需 2 個時脈週期才能完成，有關此 CPU 的\n敘述，下列何者正確？","options":["此 CPU 每秒鐘震盪 4 億次","此 CPU 的時脈週期為 0.25 ms(毫秒)","此 CPU 指令執行速度為 2000 MIPS(每秒可執行 2000 Million 個指令)","此 CPU 執行 1 億個指令需 0.5 秒"],"answer":"C","official":"(A) 時脈頻率 4G Hz 為每秒震盪 40 億次\n(B) 時脈週期為 0.25 ns\n(D) CPU 每秒可完成 20 億個指令，1 億個指令需花\n0.05 秒完成"},{"id":"110-5-A-28","exam":"110-5","q":28,"unit":"電腦與數位資料","topic":"數位科技","stem":"有關各種記憶單元的敘述，下列何者正確？","options":["SSD 固態硬碟所使用的記憶體元件大多為快閃記憶體(Flash ROM)","DDR4 記憶體模組所使用的記憶體元件大多為靜態隨機存取記憶體(SRAM)","Cache 快取記憶體所使用的記憶體元件大多為動態隨機存取記憶體(DRAM)","USB 隨身碟所使用的記憶體元件大多為暫存器(Register)"],"answer":"A","official":"(B) DDR4 主要用於主記憶體，記憶體元件為 DRAM\n(C) 快取記憶體元件大多為 SRAM\n(D) USB 隨身碟使用記憶體元件大多為 Flash ROM"},{"id":"110-5-A-29","exam":"110-5","q":29,"unit":"試算表與資料處理","topic":"數位科技","stem":"有關各種軟體的敘述，下列何者正確？","options":["學校委請廠商設計，用於管理學生資料的學籍系統屬於系統軟體","編譯器(compiler)及直譯器(interpreter)屬於應用軟體","資料庫管理系統和網站編輯程式均屬於系統軟體","Apple iWork 及 Apache OpenOffice 均屬於應用軟體"],"answer":"D"},{"id":"110-5-A-30","exam":"110-5","q":30,"unit":"網頁與程式設計","topic":"數位科技","stem":"下列各種檔案類型，哪些不屬於開放格式？","options":[".pdf、.html、.xml",".dotx、.xltx、.potx",".odt、.ods、.odp",".ufo、.psd、.ai"],"answer":"D","official":".ufo、.psd、.ai 檔為特定軟體所支援的格式，為封閉\n格式"},{"id":"110-5-A-31","exam":"110-5","q":31,"unit":"網路與通訊","topic":"數位科技","stem":"陳老師用筆電連上學校網站，在瀏覽器上輸入學校網站的網址後卻無法連線成功，後來改成直接輸入學\n校網站伺服器的 IPv4 位址，便可順利連上網站，請問發生上述的情況，最有可能的原因為何？","options":["陳老師的電腦未正確設定 DNS 伺服器的 IP 位址","陳老師筆電的無線網卡故障，無法進行 Wi-Fi 連線","學校的 FTP 伺服器故障，無法進行連線","學校關閉對外網路，只能在區域網路內部連線"],"answer":"A","official":"輸入網頁伺服器的 IP 位址後可正常連線，代表網頁\n伺服器並無故障，且對外網路也可進行連線。最有可\n能的原因為 DNS 伺服器設定有問題，故無法將網址\n中的網域名稱轉成正確的 IP 位址，所以輸入網址時\n無法連線"},{"id":"110-5-A-32","exam":"110-5","q":32,"unit":"網路與通訊","topic":"數位科技","stem":"有關 IP 之敘述，下列何者錯誤？","options":["IP 位址根據使用範圍及規模，分成 A、B、C、D、E 五個等級，但一般只有 A、B、C 三個等級的\nIP 位址可在網際網路上使用","Class A 等級的網路可分配的主機位址最多，而 Class C 等級的網路可分配的主機位址較少","IP 位址的第一組數字若為 0~128，屬於 Class A 等級的 IP 位址","前兩組數字為 192.168 的 IP 位址，為 Class C 的私有 IP(Private IP)位址"],"answer":"C","official":"(C) Class A 等級的 IP 位址第一組數字為 0~127"},{"id":"110-5-A-33","exam":"110-5","q":33,"unit":"雲端與新興科技","topic":"數位科技","stem":"根據雜誌報導，日本因應老年化社會，提出物聯網(IoT)智慧冰箱監控服務，對長者或病患家庭，提供\n24 小時冰箱開關統計，超過一定時間沒動過冰箱，就會通知親屬或約定醫院，確認住戶是否發生意外。\n有關智慧冰箱功能與物聯網對應關係的敘述，下列何者錯誤？","options":["智慧冰箱門把上的感測器，能偵測是否有人開啟冰箱，屬於物聯網中的感知層","智慧冰箱將每天開關次數及時間記錄於資料庫中，屬於物聯網中的資料層","智慧冰箱同時也透過 Wi-Fi 將相關記錄上傳至住宅管理公司的監測系統，屬於物聯網中的網路層","住宅管理公司的監測系統採用人工智慧技術，找出可能有異狀的住戶並通知親屬，屬於物聯網中的\n應用層"],"answer":"B"},{"id":"110-5-A-34","exam":"110-5","q":34,"unit":"雲端與新興科技","topic":"數位科技","stem":"有關雲端服務的敘述，下列何者正確？","options":["使用者須在電腦上安裝相關軟體才能使用雲端服務","程式開發者在雲端服務提供者的平台上開發應用程式，屬於 IaaS 類型的服務","一般使用者使用的雲端服務如雲端硬碟、線上郵件等，屬於 SaaS 類型服務","企業向雲端服務提供者租用伺服器、儲存空間，省下購買及維護硬體的成本，屬於 PaaS 類型服務"],"answer":"C","official":"(A) 雲端服務可直接透過瀏覽器使用服務，不一定得\n先安裝軟體\n(B) 應屬於 PaaS\n(D) 應屬於 IaaS"},{"id":"110-5-A-35","exam":"110-5","q":35,"unit":"電子商務與數位服務","topic":"數位科技","stem":"行政院推行振興五倍券政策，鼓勵民眾以數位五倍券的方式進行數位綁定，而數位綁定的方式包括有：\n綁定信用卡、電子票證、行動支付。請問民眾進行數位綁定後，下列何種支付方式較不可能使用數位五\n倍券進行消費？","options":["利用電信公司小額付費服務進行付款","利用 Apple Pay 或 Google Pay 進行付款","利用悠遊卡或一卡通進行付款","利用 Pi 拍錢包或街口支付進行付款"],"answer":"A","official":"可參考 https://hpm.5000.gov.tw/cp.aspx?n=299\n(A) 電信小額付費機制為使用手機門號，透過電信公\n司出帳進行消費，不符合數位綁定資格\n(B) 使用 Apple Pay 或 Google Pay 付款，為綁定信用\n卡的付款方式\n(C) 悠遊卡和一卡通為綁定電子票證的付款方式\n(D) Pi 拍錢包和街口支付為綁定行動支付的付款方式"},{"id":"110-5-A-36","exam":"110-5","q":36,"unit":"雲端與新興科技","topic":"數位科技","stem":"許多同學喜歡在 Instagram 上發佈限時動態，當使用者以相機鏡頭拍照時，透過 Instagram 上所提供的濾\n鏡特效，可偵測人臉，並在使用者頭上或臉部加上頭飾、鬍子、帽子、眼鏡等虛擬效果，請問這樣的技\n術稱為何？","options":["VR (Virtual Reality)","AR (Augmented Reality)","NFT (Non-Fungible Token)","LBS (Location Based Service)"],"answer":"B","official":"VR 虛擬實境為利用電腦技術模擬出擬真世界，而 AR\n擴增實境則是搭配真實環境設計出適合的虛擬影\n像。如 Instagram 的濾鏡特效，便是在真實人臉上加\n上虛擬動畫效果，即是 AR 的應用之一"},{"id":"110-5-A-37","exam":"110-5","q":37,"unit":"資安與資訊倫理","topic":"數位科技","stem":"日前有網紅利用 AI 深度偽造(Deepfake)技術，強調以「挖面」方式將多名女性公眾人物的臉「移植」\n到色情片女優身上，販售非法合成影片獲得不法利益，有關其犯罪行為及其涉犯的法律，下列敘述何\n者不正確？","options":["將他人長相特徵等個人資料蒐集後用於不法之利益，涉犯「個人資料保護法」","藉由散佈文字、圖畫毀損他人名譽，涉犯刑法「誹謗罪」","製作、散佈色情影片，涉犯刑法「散布、販賣猥褻物品及製造持有罪」","以造假影片欺騙消費者，涉犯刑法「詐欺罪」"],"answer":"D","official":"該案例中，網紅販售不法影片時，已強調是利用\nDeepfake 進行移植臉部合成，滿足購買者對公眾人物\n的幻想，故與詐欺較無關係"},{"id":"110-5-A-38","exam":"110-5","q":38,"unit":"文書與簡報","topic":"數位科技","stem":"在文書處理軟體(Word)中，要在資料前加入不同階層的編號，以\n完成如圖(一)所示的文件，應使用何種功能？","options":["多層次清單","項目符號","大綱階層","交互參照"],"answer":"A","official":"「項目符號」為在文字前加上 ● 或 ○ 等符號，而「編號」則在文字前依序加上數字 1、2 或是 I、II 等符號。此題有不同階層加上不同種編號，則為「多層次清單」的功能","scan":"data:image/webp;base64,"},{"id":"110-5-A-39","exam":"110-5","q":39,"unit":"文書與簡報","topic":"數位科技","stem":"在文書處理軟體(Word)中，有關合併列印功能的敘述，下列何者不正確？","options":["啟動合併列印時，可選擇主文件的類型有信件、電子郵件訊息、信封、標籤、目錄","選取收件者讀入資料來源檔時，可選擇的資料來源檔有Word 檔案、Excel 檔案、Access 檔案、網頁.html\n檔、純文字.txt 檔、.csv 檔等類型","編輯收件者清單時可進行篩選和排序，挑選出符合條件的資料","插入合併欄位的功能變數時，變數前後會以〈〉符號顯示"],"answer":"D","official":"(D) 應為《》山型符號"},{"id":"110-5-A-40","exam":"110-5","q":40,"unit":"文書與簡報","topic":"數位科技","stem":"在簡報軟體(PowerPoint)進行列印功能時，下列何者並非 PowerPoint 能選擇的列印模式？","options":["大綱","母片","備忘稿","講義"],"answer":"B"},{"id":"110-5-A-41","exam":"110-5","q":41,"unit":"試算表與資料處理","topic":"數位科技","stem":"在電子試算表軟體(Excel)中，若在儲存格 A1 輸入下列公式，則 A1 顯示為何？\n「=OR(MOD(10,2)=0,10^2<>100,2^11>2000,-3^2<>9)」","options":["FALSE","TRUE","#NAME","#VALUE"],"answer":"B","official":"OR 函數中任一條件為 TRUE 時，結果即為 TRUE，\n此題 函 數中第一個 條 件 MOD(10,2)=0 結果 為\nTRUE，故此 OR 函數計算結果為 TRUE"},{"id":"110-5-A-42","exam":"110-5","q":42,"unit":"試算表與資料處理","topic":"數位科技","stem":"在電子試算表軟體(Excel)中，儲存格 A1：C5 原有資料如圖(二)，若\n在儲存格 G4 輸入公式「=C$5-$B4」，並將此儲存格公式複製到 E1\n儲存格後，請問 E1 儲存格顯示內容為何？","options":["#REF!","=A5-B1","49","496"],"answer":"C","official":"E1 儲存格公式應為「=A$5-$B1」，故顯示結果為 49","scan":"data:image/webp;base64,"},{"id":"110-5-A-43","exam":"110-5","q":43,"unit":"試算表與資料處理","topic":"數位科技","stem":"在電子試算表軟體(Excel)中，若只要顯示符合特定條件的資料，如只顯示成績低於 60 分的資料，而其他資料則隱藏不顯示，應使用何種功能？","options":["設定格式化條件", "資料剖析", "資料驗證", "資料篩選"],"answer":"D","scan":"data:image/webp;base64,"},{"id":"110-5-A-44","exam":"110-5","q":44,"unit":"網路與通訊","topic":"數位科技","stem":"小明與專題組員想了解民眾對於 COVID-19 疫苗的認識，於是利用 Google 所提供的服務，設計一線上\n問卷，並將問卷的網址公佈在網路上，請網友幫忙填寫問卷。請問他們所使用的服務應為何？","options":["Google Jamboard","Google Meet","協作平台","Google 表單"],"answer":"D"},{"id":"110-5-A-45","exam":"110-5","q":45,"unit":"影像與多媒體","topic":"數位科技","stem":"在數位影像處理中，有關 RGB 色彩模型之敘述，下列何者正確？","options":["R 為紅色，G 為藍色，B 為綠色","該混色模式屬於減色法","RGB 三種原色各有 256 種不同亮度的變化","三原色皆以最高亮度混合而成所得顏色為黑色"],"answer":"C","official":"(A) R 為紅色，G 為綠色，B 為藍色\n(B) 該混色模式屬於加色法\n(D) 三原色各以最高亮度混合而成所得顏色為白色"},{"id":"110-5-A-46","exam":"110-5","q":46,"unit":"影像與多媒體","topic":"數位科技","stem":"有關影像處理軟體如 PhotoImpact 或 Photoshop 所提供的選取工具，下列敘述何者不正確？","options":["矩形選取工具可選取矩形形狀的影像範圍","套索工具適合選取形狀不規則的影像範圍","魔術棒工具適合選取顏色複雜且差異較大的影像範圍","較複雜的影像不易使用選取工具選取影像範圍時，可利用擷取物件或物件選取功能，讓軟體透過 AI\n演算法自動選取主體物件"],"answer":"C","official":"(C) 魔術棒工具適合選取顏色一致或相近的影像範圍"},{"id":"110-5-A-47","exam":"110-5","q":47,"unit":"網頁與程式設計","topic":"數位科技","stem":"若要讓網頁中的圖片具有超連結功能，例如點擊圖片(TCTE.png)後，能連結到入學測驗中心的網站\n(https://www.tcte.edu.tw/index.php)，請問正確的 HTML 語法應為何？","options":["<img src=\"TCTE.png\"><a href = \"https://www.tcte.edu.tw/index.php\"></a>","<a href = \"https://www.tcte.edu.tw/index.php\"><img src=\"TCTE.png\"></a>","<img src=\" https://www.tcte.edu.tw/index.php \"><a href = \" TCTE.png \"></a>","<a href = \"TCTE.png\"><img src=\"https://www.tcte.edu.tw/index.php\"></a>"],"answer":"B"},{"id":"110-5-A-48","exam":"110-5","q":48,"unit":"電子商務與數位服務","topic":"數位科技","stem":"請問小朱在學期間透過 FB 社團和 Instagram 社群與網友進行交易的方式，屬於電子商務中的何種類型？","options":["C2B","C2C","B2B","B2C"],"answer":"B","group":"110-5-48-50"},{"id":"110-5-A-49","exam":"110-5","q":49,"unit":"網頁與程式設計","topic":"數位科技","stem":"若小朱想自學網頁設計語言，開發屬於自己品牌的購物網站，請問下列何種程式語言較不適用？","options":["VBA","PHP","JSP","JavaScript"],"answer":"A","official":"VBA 為設計使用於 Office 文件中的巨集程式之語\n法，無法用於設計網頁程式","group":"110-5-48-50"},{"id":"110-5-A-50","exam":"110-5","q":50,"unit":"電子商務與數位服務","topic":"數位科技","stem":"小朱發現自學網頁設計實在太過困難，而且自行架設網站也需要額外成本，但依然希望有個屬於自己品\n牌且具有獨立網址的官方網站，請問小朱透過何種類型的電子商務平台來販賣商品最為適合？","options":["透過網路開店平台開設線上購物商店","透過募資平台提案新商品","在網路拍賣平台上上架商品","在購物中心/購物商城開店"],"answer":"A","official":"因題目敘述使用者希望有獨立網址的網站，故採用網\n路開店平台仍可申請自己品牌的網域名稱或網址。而\n(B)(C)(D)選項都無法有自己的網址","group":"110-5-48-50"}]);
